package xyz.ronella.gosu.lsp.handlers;

import org.eclipse.lsp4j.*;
import org.eclipse.lsp4j.jsonrpc.messages.Either;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Handles textDocument/codeAction requests.
 *
 * Produces {@link CodeActionKind#QuickFix} actions for the ANTLR4 error
 * messages generated by {@link xyz.ronella.gosu.lsp.analysis.DiagnosticsPublisher}.
 * Supported fixes:
 * <ul>
 *   <li>"missing ';'" — inserts a semicolon at the diagnostic end position</li>
 *   <li>"extraneous input …", "mismatched input …", "no viable alternative …"
 *       — deletes the offending token at the diagnostic range</li>
 * </ul>
 */
public class CodeActionHandler {

    /** Creates a new {@code CodeActionHandler}. */
    public CodeActionHandler() {
        // no state to initialise
    }

    /** Returns quick-fix actions for the given diagnostics at the specified range in {@code uri}. */
    public List<Either<Command, CodeAction>> getActions(
            String uri, Range range, List<Diagnostic> diagnostics) {
        if (diagnostics == null || diagnostics.isEmpty()) return Collections.emptyList();

        List<Either<Command, CodeAction>> actions = new ArrayList<>();
        for (Diagnostic d : diagnostics) {
            CodeAction action = buildFix(uri, d);
            if (action != null) {
                actions.add(Either.forRight(action));
            }
        }
        return actions;
    }

    // ── Fix builders ──────────────────────────────────────────────────────

    private static CodeAction buildFix(String uri, Diagnostic diag) {
        String msg = diag.getMessage();
        if (msg == null) return null;

        if (msg.contains("missing ';'")) {
            Position insertPos = diag.getRange().getEnd();
            TextEdit edit = new TextEdit(new Range(insertPos, insertPos), ";");
            return makeAction("Insert ';'", uri, diag, edit);
        }

        if (msg.startsWith("extraneous input")
                || msg.startsWith("mismatched input")
                || msg.startsWith("no viable alternative")) {
            TextEdit edit = new TextEdit(diag.getRange(), "");
            return makeAction("Remove unexpected token", uri, diag, edit);
        }

        return null;
    }

    private static CodeAction makeAction(
            String title, String uri, Diagnostic diag, TextEdit edit) {
        WorkspaceEdit wsEdit = new WorkspaceEdit();
        wsEdit.setChanges(Map.of(uri, List.of(edit)));

        CodeAction action = new CodeAction(title);
        action.setKind(CodeActionKind.QuickFix);
        action.setDiagnostics(List.of(diag));
        action.setEdit(wsEdit);
        return action;
    }
}
